}

gint wx, wy;

i_update_middle_button (w_current, action, _("Move"));

if (o_select_return_first_object(w_current)) {
  o_redraw_cleanstates(w_current);
  if (g_action_get_position (TRUE, &wx, &wy)) {
    o_move_start(w_current, wx, wy);
  }
